@startuml

class Ingredient {
  + name : string
  + measuringUnit : string
  + quantityInStock : float
}

class Dish {
  + name : string
  + id : int
}

class Table {
  + id : int
  + maxAmountOfPeople : int
}

class Meal {
  + date : date
  + startTime : time
  + endTime : time
}

class Waiter {
  + id : int
  + name : string
  + address : string
  + phone : string
}

class Client {
  + taxIdentificationNumber : string
  + name : string
  + address : string
}

class DishUsage {
  + quantity : float
}

Ingredient "1..*" -- "1..*" Dish : composed of
Dish "1" -- "*" DishUsage
Ingredient "1" -- "*" DishUsage

Meal "1" -- "1" Table : takes place at
Meal "1" -- "0..1" Client : consumed by
Meal "1" -- "1" Waiter : responsible waiter
Meal "1" -- "1..*" DishUsage : includes

@enduml

